import { createExhibitionFloorplan, exhibitionRoomRoute } from './exhibitionFloorplan.js';
import { exhibitionPictureGroup } from './exhibitionImage.js';

export const EXHIBITION_INTRO_WIDTH = 3.55;

export function galleryPoint(room, x, y, z) {
  const c = Math.cos(room.angle), s = Math.sin(room.angle);
  return [room.x + x * c + z * s, y, room.z - x * s + z * c];
}
export function galleryLocal(room, x, z) {
  const c = Math.cos(room.angle), s = Math.sin(room.angle), dx = x - room.x, dz = z - room.z;
  return [dx * c - dz * s, dx * s + dz * c];
}
const inside = (area, x, z, margin = 0) => Math.abs(x - area.x) <= area.width / 2 - margin && Math.abs(z - area.z) <= area.depth / 2 - margin;

// Doorways own a landing inside each room, as well as the opening itself.
// Installations must clear the whole landing, including their rotated base.
export function galleryDoorLandings(plan, area) {
  return plan.doors.filter(door=>door.a===area.index||door.b===area.index).map(door=>{
    const [x,z]=galleryLocal(area,...door.points[door.a===area.index?0:1]);
    const side=Math.abs(x)>area.localWidth/2-.1;
    return {x:side?x-Math.sign(x)*1.6:x,z:side?z:z-Math.sign(z)*1.6,width:side?3.2:door.width+1,depth:side?door.width+1:3.2};
  });
}

// Each forward threshold carries the next chapter's own title. Mount the ink
// on the lintel facing the room being left, clear of objects and the opening.
export function galleryWayfinding(plan, rooms) {
  return plan.doors.filter(door=>door.primary && rooms[door.b-1]).map(door=>{
    const room=plan.rooms[door.a], next=rooms[door.b-1], point=door.points[0];
    const alongX=Math.abs(point[0]-room.x)>room.width/2-.1;
    const nx=alongX?Math.sign(room.x-point[0]):0,nz=alongX?0:Math.sign(room.z-point[1]);
    return {title:next.title,number:String(next.index+1).padStart(2,'0'),width:Math.min(4.4,door.width-.55),
      anchor:[point[0]+nx*.17,4.92,point[1]+nz*.17],rotation:Math.atan2(nx,nz)};
  });
}
const overlaps=(a,b)=>Math.abs(a.x-b.x)<(a.width+b.width)/2 && Math.abs(a.z-b.z)<(a.depth+b.depth)/2;
function installationDimensions(stop) {
  if(stop.form==='photographs')return {width:exhibitionPictureGroup(stop.images).span,depth:.5};
  if(stop.form==='photo-ribbon')return {width:3.8,depth:2.8};
  if(['photo-viewer','reading-roll'].includes(stop.form))return {width:3.2,depth:2.8};
  if(stop.form==='photo-carousel')return {width:3,depth:3,radial:true};
  if(['light-table','interactive-table'].includes(stop.form))return {width:3.8,depth:2.2};
  return {width:stop.form?.startsWith('interactive-')?3.1:2.8,depth:2.2};
}
function previewFootprint(stop, area, x, z, rotation) {
  const {width,depth,radial}=installationDimensions(stop), c=Math.abs(Math.cos(rotation)),s=Math.abs(Math.sin(rotation));
  if(radial)return {room:area,x,z,width,depth};
  return {room:area,x,z,width:width*c+depth*s,depth:width*s+depth*c};
}

// The sequence is editorial. Architecture arranges it around courtyards,
// while deterministic doors and reading zones keep every repeat visit stable.
export function createGalleryArchitecture(rooms, stops, closing, citations, extraDepth = [], layout = {}) {
  const inputs = [{ id: 'entrance', title: 'Entrance', width: 15.6, depth: 12.2 }, ...rooms.map(room => ({
    id: room.index, title: room.title, width: room.index === rooms.length - 1 ? 13.6 : 12,
    depth: (room.stopIndices.length===0?10.4:room.stopIndices.length===1?12.8:15.2 + Math.max(0, Math.ceil(room.stopIndices.length / 2) - 1) * 6.2) + (room.index === rooms.length - 1 && closing ? 4 : 0) + (extraDepth[room.index] || 0),
  }))];
  // A square cell fits a room in either orientation. Its occupied footprint
  // remains rectangular, leaving deliberate open space around the connecting halls.
  // Keep the entrance exit ahead. Mirroring varies handedness without putting
  // a doorway behind the entrance panel.
  const plan = createExhibitionFloorplan(inputs.map(item => ({ ...item, width: Math.max(item.width, item.depth) })), (layout.seed || 0) & 4, layout.family || 'courtyard');
  const origin = plan.rooms[0];
  const ox = origin.x, oz = origin.z;
  plan.rooms.forEach((area, index) => {
    area.x -= ox; area.z -= oz;
    const previous = index ? plan.rooms[index - 1] : null;
    area.angle = previous ? Math.atan2(-(area.x - previous.x), -(area.z - previous.z)) : 0;
    area.localWidth = inputs[index].width; area.localDepth = inputs[index].depth;
    const turned = Math.abs(Math.sin(area.angle)) > .5;
    area.width = turned ? area.localDepth : area.localWidth;
    area.depth = turned ? area.localWidth : area.localDepth;
    area.chapterIndex = index - 1;
  });
  // Pack unequal rooms with per-row and per-column clearances. The entrance
  // must not inherit an oversized cell and an unnecessarily long corridor.
  const columns=new Map([[0,12]]),rows=new Map([[0,12]]);
  for(const area of plan.rooms){columns.set(area.cell[0],Math.max(columns.get(area.cell[0])||0,area.width));rows.set(area.cell[1],Math.max(rows.get(area.cell[1])||0,area.depth));}
  const centres=sizes=>{const result=new Map(),keys=[...sizes.keys()].sort((a,b)=>a-b);result.set(keys[0],0);for(let i=1;i<keys.length;i++)result.set(keys[i],result.get(keys[i-1])+(sizes.get(keys[i-1])+sizes.get(keys[i]))/2+4);return result;};
  const xs=centres(columns),zs=centres(rows),entranceX=xs.get(plan.rooms[0].cell[0]),entranceZ=zs.get(plan.rooms[0].cell[1]);
  for(const area of plan.rooms){area.x=xs.get(area.cell[0])-entranceX;area.z=zs.get(area.cell[1])-entranceZ;}
  // A short, wide threshold reveals the first gallery beside the entrance
  // panel. Later rooms retain the selected plan and their individual turns.
  const firstGallery=plan.rooms[1];
  const entranceGap=firstGallery?plan.rooms[0].z-plan.rooms[0].depth/2-2-(firstGallery.z+firstGallery.depth/2):0;
  for(const area of plan.rooms.slice(1))area.z+=entranceGap;
  plan.courtyard={x:xs.get(0)-entranceX,z:zs.get(0)-entranceZ,width:columns.get(0),depth:rows.get(0)};
  plan.doors = plan.doors.filter(door => {
    if (door.primary) return true;
    // The final reading wall is complete, with its notes and citations nearby.
    const last = plan.rooms.length - 1;
    if (door.a !== last && door.b !== last) return true;
    const area = plan.rooms[last], other = plan.rooms[door.a === last ? door.b : door.a];
    return galleryLocal(area, other.x, other.z)[1] > -1;
  });
  plan.doors.forEach(door => {
    const entranceDoor=door.primary&&door.a===0&&door.b===1;
    if(entranceDoor)door.width=7;
    const a=plan.rooms[door.a],b=plan.rooms[door.b];
    const dx=Math.sign(b.x-a.x);
    function threshold(area,other) {
      const direction=galleryLocal(area,other.x,other.z);
      let x=0,z=0;
      if(Math.abs(direction[0])>Math.abs(direction[1])) {x=Math.sign(direction[0])*area.localWidth/2;z=-area.localDepth/2+3.3;}
      else z=Math.sign(direction[1])*area.localDepth/2;
      const p=galleryPoint(area,x,0,z);return [p[0],p[2]];
    }
    const preferred=[threshold(a,b),threshold(b,a)], axis=dx?'x':'z', cross=dx?'z':'x';
    const extent=area=>cross==='x'?area.width:area.depth;
    const margin=door.width/2+.42;
    const lo=Math.max(a[cross]-extent(a)/2,b[cross]-extent(b)/2)+margin;
    const hi=Math.min(a[cross]+extent(a)/2,b[cross]+extent(b)/2)-margin;
    const aLocal=galleryLocal(a,...preferred[0]);
    const sideExit=Math.abs(aLocal[0])>a.localWidth/2-.1;
    const wanted=entranceDoor?1.5:preferred[sideExit?0:1][dx?1:0];
    const aligned=Math.max(lo,Math.min(hi,wanted));
    const direction=Math.sign(b[axis]-a[axis]);
    const edge=(area,sign)=>area[axis]+sign*(axis==='x'?area.width:area.depth)/2;
    door.points=dx?[[edge(a,direction),aligned],[edge(b,-direction),aligned]]:[[aligned,edge(a,direction)],[aligned,edge(b,-direction)]];
    // Aligned thresholds produce one straight connection. Reading positions
    // adapt to the door clearance instead of adding a disorienting chicane.
    door.route=door.points;
    door.areas=door.route.slice(1).map((q,i)=>{const p=door.route[i],horizontal=Math.abs(q[0]-p[0])>.01;return {x:(p[0]+q[0])/2,z:(p[1]+q[1])/2,width:horizontal?Math.abs(q[0]-p[0])+door.width:door.width,depth:horizontal?door.width:Math.abs(q[1]-p[1])+door.width,corridor:door};});
  });
  plan.corridors=plan.doors.flatMap(door=>door.areas);
  const occupied=[...plan.rooms,...plan.corridors];
  // Render only the boundary of the floor union. Shared edges disappear at
  // doorways and corridor elbows, keeping the actual model and walking map aligned.
  plan.walls=[];
  for(const area of occupied) for(const [axis,sign] of [['x',-1],['x',1],['z',-1],['z',1]]) {
    const vertical=axis==='x',otherAxis=vertical?'z':'x',length=vertical?area.depth:area.width;
    const fixed=area[axis]+sign*(vertical?area.width:area.depth)/2;
    let segments=[[area[otherAxis]-length/2,area[otherAxis]+length/2]];
    for(const other of occupied) {
      if(other===area)continue;
      const across=vertical?other.width:other.depth,along=vertical?other.depth:other.width;
      if(Math.abs(fixed+sign*.01-other[axis])>=across/2)continue;
      const lo=other[otherAxis]-along/2,hi=other[otherAxis]+along/2;
      segments=segments.flatMap(([a,b])=>hi<=a||lo>=b?[[a,b]]:[[a,Math.min(b,lo)],[Math.max(a,hi),b]].filter(([x,y])=>y-x>.02));
    }
    for(const [start,end] of segments)plan.walls.push({room:area.corridor?undefined:area.index,corridor:area.corridor,x:vertical?fixed:(start+end)/2,z:vertical?(start+end)/2:fixed,width:vertical?.24:end-start,depth:vertical?end-start:.24});
  }
  plan.footprints = [];
  const nextDepth=extraDepth.slice(); let expand=false;
  rooms.forEach((room, index) => {
    const area = plan.rooms[index+1]; room.space = area;
    // Start beside the introduction and finish towards the next doorway.
    // A room's handedness follows its count and exit, with a stable seed when
    // a straight exit gives both sides equal standing. The first bay keeps
    // its open sightline on the opposite side of the introduction.
    const exit=plan.doors.find(door=>door.primary&&door.a===area.index);
    const exitPoint=exit?galleryLocal(area,...exit.points[0]):null;
    const exitSide=exitPoint&&Math.abs(exitPoint[0])>area.localWidth/2-.1?Math.sign(exitPoint[0]):0;
    const introSide=index===0?-1:exitSide?exitSide*(room.stopIndices.length%2?1:-1):((layout.seed||0)+index+room.stopIndices.length)%2?-1:1;
    room.introSide=introSide;
    room.introAnchor = galleryPoint(area, introSide*(area.localWidth/2-.15), 2.3, area.localDepth/2-3.1);
    room.introEye = galleryPoint(area, introSide*(area.localWidth/2-5.95), 1.72, area.localDepth/2-3.1);
    room.introTarget = galleryPoint(area, introSide*(area.localWidth/2-.15), 2.04, area.localDepth/2-3.1);
    room.introRotation = area.angle - introSide*Math.PI/2;
    // Reserve the introduction and the widest wall group, including its mount.
    // Paired reading positions stay together so the visit still advances.
    const wallSpan=Math.max(0,...room.stopIndices.map(i=>stops[i].floor?0:exhibitionPictureGroup(stops[i].images).span));
    const firstBayDepth=Math.max(6.5,3.1+(EXHIBITION_INTRO_WIDTH+wallSpan)/2+.55);
    // Floor objects face inward. Their display width therefore occupies the
    // length of the wall, including the full movement of a folding carrier.
    const bayDepth=Math.max(3.3,...room.stopIndices.filter(i=>stops[i].floor).map(i=>installationDimensions(stops[i]).width));
    const slots = [];
    for (let z=area.localDepth/2-firstBayDepth; z>=-area.localDepth/2+(index===rooms.length-1&&closing?8:4.5)-.01; z-=6.2) {
      for (const side of [introSide,-introSide]) {
        const sideDoor=plan.doors.some(door => {
          if (door.a!==area.index&&door.b!==area.index) return false;
          const p=door.points[door.a===area.index?0:1], local=galleryLocal(area,...p);
          return Math.abs(local[0]-side*area.localWidth/2)<.1 && Math.abs(z-local[1])<3.95;
        });
        const standingBay={x:side*(area.localWidth/2-2.65),z,width:3.9,depth:bayDepth};
        if (!sideDoor && !galleryDoorLandings(plan,area).some(landing=>overlaps(standingBay,landing))) slots.push({side,z});
      }
    }
    if(slots.length<room.stopIndices.length) {nextDepth[index]=(extraDepth[index]||0)+6.2;expand=true;return;}
    // The first work belongs beside the introduction. The second provides
    // the entrance sightline, sharing the first pair's forward standing line.
    // A single-work gallery uses that work as its landmark directly.
    const preview=index===0?room.stopIndices[room.stopIndices.length>1?1:0]:undefined;
    const reserved=slots.findIndex(slot=>slot.side===1);
    const previewX=area.localWidth/2-1.9,previewZ=area.localDepth/2-firstBayDepth-1.7;
    const previewRotation=Math.atan2(-previewX,1.7);
    const footprint=preview===undefined?null:previewFootprint(stops[preview],area,previewX,previewZ,previewRotation);
    const previewClear=footprint && Math.abs(footprint.x)+footprint.width/2<area.localWidth/2-.3 && Math.abs(footprint.z)+footprint.depth/2<area.localDepth/2-.6 && !galleryDoorLandings(plan,area).some(landing=>overlaps(footprint,landing));
    const available=previewClear?slots.filter((slot,i)=>i!==reserved):slots;
    let slotIndex=0;
    room.stopIndices.forEach(stopIndex => {
      const stop=stops[stopIndex], slot=stopIndex===preview&&previewClear?{side:1,z:area.localDepth/2-firstBayDepth}:available[slotIndex++];
      stop.entrancePreview=false;
      if (!slot) throw new Error('The room has no clear reading position');
      const {side,z}=slot, x=side*(stop.floor ? area.localWidth/2-2.65 : area.localWidth/2-.16);
      const y=stop.form==='globe'||stop.form==='photo-carousel'?1.95:stop.form==='photo-ribbon'?1.67:stop.form==='photo-viewer'?2.08:stop.form==='reading-roll'?2.03:stop.form==='hanging-scroll'?2.6:stop.form==='reading-case'?1.25:stop.form==='light-table'?1.95:stop.form==='folio'?1.9:stop.form==='interactive-display'?2.05:stop.floor?1.6:2.65;
      const eye=[stop.form==='globe'?-side*.65:0,1.72,z];
      stop.anchor=galleryPoint(area,x,y,z); stop.eye=galleryPoint(area,...eye);
      stop.target=galleryPoint(area,x,stop.floor?y:2.25,z);
      stop.rotation=area.angle-side*Math.PI/2; stop.z=stop.anchor[2]; stop.side=side;
      if(stopIndex===preview&&previewClear) {
        stop.anchor=galleryPoint(area,previewX,y,previewZ);
        stop.target=galleryPoint(area,previewX,stop.floor?y:2.25,previewZ);
        stop.eye=galleryPoint(area,0,1.72,area.localDepth/2-firstBayDepth);
        stop.rotation=area.angle+Math.atan2(-previewX,1.7);stop.z=stop.anchor[2];stop.entrancePreview=true;
        plan.previewStop=stopIndex;
        plan.footprints.push(footprint);
      } else if(stop.floor) {
        const physical=previewFootprint(stop,area,x,z,-side*Math.PI/2);
        plan.footprints.push({...physical,width:Math.max(3.9,physical.width),depth:Math.max(3.3,physical.depth)});
      }
    });
  });
  if(expand)return createGalleryArchitecture(rooms,stops,closing,citations,nextDepth,layout);
  const lobby=plan.rooms[0];
  const boardX=-4.6,boardZ=-3.2;
  plan.entrance={ anchor:galleryPoint(lobby,boardX,2.625,boardZ), target:galleryPoint(lobby,boardX,2.36,boardZ), eye:galleryPoint(lobby,boardX,1.72,5.6), rotation:0 };
  plan.footprints.push({room:lobby,x:boardX,z:boardZ,width:5.8,depth:.25});
  if (closing&&rooms.length) {
    const room=plan.rooms.at(-1), back=-room.localDepth/2;
    closing.anchor=galleryPoint(room,-2.3,2.5,back+.15); closing.target=galleryPoint(room,-2.3,2.25,back+.15);
    closing.eye=galleryPoint(room,-2.3,1.72,back+6.4); closing.rotation=room.angle;
    closing.notesPosition=galleryPoint(room,-.55,0,back+2.6); closing.notesRotation=room.angle;
  }
  if(citations&&rooms.length) {
    const room=plan.rooms.at(-1), back=-room.localDepth/2;
    citations.anchor=galleryPoint(room,room.localWidth/2-.16,2.25,back+5.1);
    citations.eye=galleryPoint(room,room.localWidth/2-6.15,1.72,back+5.1);
    citations.target=galleryPoint(room,room.localWidth/2-.16,2.15,back+5.1); citations.rotation=room.angle-Math.PI/2;
  }
  const areas=[...plan.rooms,...plan.corridors];
  const minX=Math.min(...areas.map(a=>a.x-a.width/2)),maxX=Math.max(...areas.map(a=>a.x+a.width/2));
  const minZ=Math.min(...areas.map(a=>a.z-a.depth/2)),maxZ=Math.max(...areas.map(a=>a.z+a.depth/2));
  plan.bounds={minX,maxX,minZ,maxZ,width:maxX-minX,depth:maxZ-minZ};
  return plan;
}

export function galleryAreaAt(plan,x,z) { return plan.rooms.find(area=>inside(area,x,z)); }
export function galleryCanStand(plan,x,z) {
  if(!plan.rooms.some(area=>inside(area,x,z))&&!plan.corridors.some(area=>inside(area,x,z))) return false;
  if(plan.walls.some(wall=>inside(wall,x,z,-.31))) return false;
  return !plan.footprints.some(f=>{const [a,b]=galleryLocal(f.room,x,z);return Math.abs(a-f.x)<f.width/2+.28&&Math.abs(b-f.z)<f.depth/2+.28;});
}

export function galleryWalkingPoints(plan,origin,eye) {
  const points=[];
  let start=galleryAreaAt(plan,origin.x,origin.z);
  const end=galleryAreaAt(plan,eye.x,eye.z);
  if(!end) return [[eye.x,1.72,eye.z]];
  if(!start) {
    const corridor=plan.doors.find(door=>door.areas.some(area=>inside(area,origin.x,origin.z)));
    if(corridor) {
      const candidates=[corridor.a,corridor.b].map(index=>({index,route:exhibitionRoomRoute(plan,index,end.index)}));
      const nearest=candidates.sort((a,b)=>a.route.length-b.route.length)[0];
      start=plan.rooms[nearest.index];
      const towards=corridor.a===start.index?corridor.route.slice().reverse():corridor.route;
      const closest=towards.reduce((best,p,i)=>Math.hypot(p[0]-origin.x,p[1]-origin.z)<Math.hypot(towards[best][0]-origin.x,towards[best][1]-origin.z)?i:best,0);
      for(const p of towards.slice(closest))points.push([p[0],1.72,p[1]]);
    } else start=plan.rooms.reduce((a,b)=>Math.hypot(a.x-origin.x,a.z-origin.z)<Math.hypot(b.x-origin.x,b.z-origin.z)?a:b);
  }
  let position=points.at(-1)||[origin.x,1.72,origin.z];
  const route=exhibitionRoomRoute(plan,start.index,end.index);
  function within(area,target) {
    const from=galleryLocal(area,position[0],position[2]),to=galleryLocal(area,target[0],target[2]);
    // Every installation is outside this central walking spine. Near neighbours
    // on the same side can be approached directly when the segment is clear.
    const distance=Math.hypot(target[0]-position[0],target[2]-position[2]);
    let clear=true;const samples=Math.max(20,Math.ceil(distance/.12));
    for(let i=1;i<samples;i++){const t=i/samples;if(!galleryCanStand(plan,position[0]+(target[0]-position[0])*t,position[2]+(target[2]-position[2])*t)){clear=false;break;}}
    if(!clear) {
      // Offset front doors join the walking spine inside the room. Moving
      // sideways along their wall would clip the solid wall beside the opening.
      const interiorZ=z=>Math.max(-area.localDepth/2+1.15,Math.min(area.localDepth/2-1.15,z));
      const fromZ=interiorZ(from[1]),toZ=interiorZ(to[1]);
      if(Math.abs(fromZ-from[1])>.01)points.push(galleryPoint(area,from[0],1.72,fromZ));
      points.push(galleryPoint(area,0,1.72,fromZ),galleryPoint(area,0,1.72,toZ));
      if(Math.abs(toZ-to[1])>.01)points.push(galleryPoint(area,to[0],1.72,toZ));
    }
    points.push(target); position=target;
  }
  for(let i=0;i<route.length-1;i++){
    const a=route[i],b=route[i+1],door=plan.doors.find(d=>(d.a===a&&d.b===b)||(d.a===b&&d.b===a));
    const first=door.points[door.a===a?0:1],second=door.points[door.a===a?1:0];
    within(plan.rooms[a],[first[0],1.72,first[1]]);
    const corridor=a===door.a?door.route:door.route.slice().reverse();
    for(const p of corridor.slice(1))points.push([p[0],1.72,p[1]]); position=[second[0],1.72,second[1]];
  }
  within(end,[eye.x,1.72,eye.z]);
  return points.filter((p,index)=>Math.hypot(p[0]-(index?points[index-1][0]:origin.x),p[2]-(index?points[index-1][2]:origin.z))>.015);
}


// Partition connecting floors into disjoint rectangles, excluding rooms.
// Shared elbows have one surface, so they cannot flicker at a shallow angle.
export function galleryCorridorTiles(plan) {
  const result=[];
  const rect=area=>[area.x-area.width/2,area.z-area.depth/2,area.x+area.width/2,area.z+area.depth/2];
  function subtract(a,b) {
    const left=Math.max(a[0],b[0]),top=Math.max(a[1],b[1]),right=Math.min(a[2],b[2]),bottom=Math.min(a[3],b[3]);
    if(left>=right||top>=bottom)return[a];
    return [[a[0],a[1],a[2],top],[a[0],bottom,a[2],a[3]],[a[0],top,left,bottom],[right,top,a[2],bottom]].filter(r=>r[2]-r[0]>.001&&r[3]-r[1]>.001);
  }
  const occupied=plan.rooms.map(rect);
  for(const area of plan.corridors) {
    let pieces=[rect(area)];
    for(const existing of occupied)pieces=pieces.flatMap(piece=>subtract(piece,existing));
    occupied.push(...pieces);
    for(const [x,z,right,bottom]of pieces)result.push({x:(x+right)/2,z:(z+bottom)/2,width:right-x,depth:bottom-z});
  }
  return result;
}
