import previews from '../data/exhibitionComponentPreviews.js';
import { sourceFingerprintValue } from './viewSnapshotCompare.js';

const fingerprints = new WeakMap();

// Previews are photographs of the registered component, separate from source
// media. A changed historical source keeps its original document carrier.
export function exhibitionComponentPreview(source, block) {
  if (!source || !['interactive', 'embed'].includes(block?.presentation)) return null;
  const preview = previews[block.source_id];
  if (!preview) return null;
  if (!fingerprints.has(source)) fingerprints.set(source, sourceFingerprintValue(source));
  return fingerprints.get(source) === preview.fingerprint ? preview : null;
}
